for i in range(1, m):
    dp[i][0] = dp[i-1][0] + grid[i][0]
for j in range(1, n):
    dp[0][j] = dp[0][j-1] + grid[0][j]

# Fill the dp table
for i in range(1, m):
    for j in range(1, n):
        # If the current cell is not the first row or column, consider the cell above or to the left
        if i > 1 and j > 1:
            dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + grid[i][j]
        # If the current cell is the first row or column, the minimum path length is the same as the cell above or to the left
        elif i > 1:
            dp[i][j] = dp[i-1][j] + grid[i][j]
        elif j > 1:
            dp[i][j] = dp[i][j-1] + grid[i][j]

# Return the minimum path length for each cell
return [dp[m-1][n-1] for _ in range(m)]

