def magic_square_test(matrix):
    """
    :type matrix: List[List[int]]
    :rtype: bool
    """
    if len(matrix) != len(matrix[0]):
        return False

    row_sum = sum(matrix[0])
    col_sum = sum(matrix)

    for i in range(len(matrix)):
        for j in range(len(matrix[0])):
            if matrix[i][j] != row_sum - matrix[i][0] - matrix[0][j]:
                return False

    row_sum = sum(matrix)
    col_sum = sum(matrix[0])

    for i in range(len(matrix)):
        for j in range(len(matrix[0])):
            if matrix[i][j] != col_sum - matrix[0][j] - matrix[0][i]:
                return False

    return True

