        if arr[i] == x:
            count += 1
        if count > n/2:
            return True
    return False

def is_majority_sorted(arr, n):
    left = 0
    right = n-1
    while left < right:
        mid = left + (right-left)//2
        if arr[mid] == x:
            return True
        if arr[mid] < x:
            left = mid + 1
        else:
            right = mid - 1
    return False

