def next_Perfect_Square(n):
    """
    :type n: int
    :rtype: int
    """
    if n == 1:
        return 1

    i = 1
    while i * i <= n:
        if i * i == n:
            return i
        i += 1

    return i * i + 1

def max_sum(arr):
    """
    :type arr: List[int]
    :rtype: int
    """
    if len(arr) < 2:
        return arr[0]

    max_sum = arr[0]
    current_sum = arr[0]

    for i in range(1, len(arr)):
        if arr[i] > arr[i-1]:
            current_sum += arr[i]
        else:
            current_sum = arr[i]

        if current_sum > max_sum:
            max_sum = current_sum

    return max_sum

