def max_sum_increasing_subseq(nums, k, i, j, memo):
    if i == j:
        return nums[i]
    if (i, j) in memo:
        return memo[(i, j)]
    if i == j - 1:
        return max(nums[i], nums[j])
    if k == 0:
        return max(nums[i], nums[j])

    max_sum = 0
    for m in range(i, j):
        max_sum = max(max_sum, max_sum_increasing_subseq(nums, k, i, m, memo) + max_sum_increasing_subseq(nums, k - 1, m + 1, j, memo))
    memo[(i, j)] = max_sum
    return max_sum

