def catalan_number(n):
    if n == 0:
        return 1
    if n == 1:
        return 1
    if n == 2:
        return 2
    catalan = [0] * (n+1)
    catalan[0] = 1
    catalan[1] = 1
    catalan[2] = 2
    for i in range(3, n+1):
        catalan[i] = catalan[i-1] + catalan[i-2]
    return catalan[n]

