def find_kth(arr1, arr2, k):
    """
    :type arr1: List[int]
    :type arr2: List[int]
    :type k: int
    :rtype: int
    """
    if len(arr1) > len(arr2):
        return find_kth(arr2, arr1, k)
    if len(arr1) == 0:
        return arr2[k-1]
    if k == 1:
        return min(arr1[0], arr2[0])
    mid = (len(arr1) + len(arr2) + k) // 2
    if arr1[mid-1] < arr2[mid]:
        return find_kth(arr1, arr2, k-mid)
    elif arr1[mid-1] > arr2[mid]:
        return find_kth(arr1, arr2, k-mid-1)
    else:
        return arr1[mid-1]

