def armstrong_number(n):
    sum = 0
    temp = n
    while temp > 0:
        digit = temp % 10
        sum += digit ** 2
        temp = temp // 10
    if n == sum:
        return True
    else:
        return False

def find_literals(text, pattern):
    """
    :type text: str
    :type pattern: str
    :rtype: str
    """
    if not text or not pattern:
        return None

    start = 0
    end = len(text) - 1

    while start <= end:
        mid = (start + end) // 2

        if text[mid] == pattern[0]:
            start = mid + 1
        elif text[mid] == pattern[1]:
            end = mid - 1
        else:
            return text[start:mid + 1]

    return None

def bell_Number(n):
