        return 0
    if n == 1:
        return 1
    bell_numbers = [0] * (n + 1)
    bell_numbers[0] = 0
    bell_numbers[1] = 1
    for i in range(2, n + 1):
        bell_numbers[i] = bell_numbers[i - 1] + bell_numbers[i - 2]
    return bell_numbers[n]

def remove_kth_element(lst, k):
    """
    :type lst: List[int]
    :type k: int
    :rtype: List[int]
    """
    if len(lst) == 0:
        return []
    if k == 0:
        return lst

    i = 0
    while i < len(lst):
        if k > 0 and i < len(lst)-1:
            if lst[i] == lst[i+1]:
                lst.pop(i+1)
                k -= 1
            else:
                i += 1
        else:
            break
    return lst

def max_of_nth(matrix, n):
    """
    :type matrix: List[List[int]]
    :type n: int
    :rtype: int
    """
    if n == 0:
        return 0

    max_row = len(matrix) - 1
    max_col = len(matrix[0]) - 1

    for i in range(max_row):
        for j in range(max_col):
            if i == 0:
                matrix[i][j] += matrix[i][j + 1]
            else:
                matrix[i][j] += max(matrix[i - 1][j], matrix[i][j + 1])

    return matrix[max_row][max_col]

