def largest_subset(nums):
    nums.sort()
    dp = [1] * len(nums)
    max_size = 1
    for i in range(1, len(nums)):
        for j in range(i):
            if nums[i] % nums[j] == 0:
                dp[i] = max(dp[i], dp[j] + 1)
        max_size = max(max_size, dp[i])
    return max_size

def get_median(list1, list2, k):
    """
    :type list1: List[int]
    :type list2: List[int]
    :type k: int
    :rtype: float
    """
    if len(list1) > len(list2):
        list1, list2 = list2, list1
    if len(list1) == 0:
        return list2[k-1]
    if k == 1:
        return min(list1, list2)
    if k % 2 == 0:
        mid = (k // 2) + 1
    else:
        mid = k // 2
    left = list1[mid-1] if mid > 0 else float('-inf')
    right = list2[mid] if mid < len(list2) else float('inf')
    return (left + right) / 2.0

