def maxAverageOfPath(matrix):
    """
    :type matrix: List[List[int]]
    :rtype: float
    """
    m = len(matrix)
    n = len(matrix[0])

    def dfs(i, j, path):
        if i == m-1 and j == n-1:
            return path

        if i < 0 or j < 0 or i >= m or j >= n:
            return float('-inf')

        if matrix[i][j] == 0:
            return float('-inf')

        if i == m-1 and j == n-1:
            return path

        left = dfs(i, j-1, path+matrix[i][j])
        right = dfs(i, j+1, path+matrix[i][j])
        top = dfs(i-1, j, path+matrix[i][j])
        bottom = dfs(i+1, j, path+matrix[i][j])

        return max(left, right, top, bottom)

    return dfs(0, 0, 0)

