def find_first_occurrence(arr, target):
    """
    :type arr: List[int]
    :type target: int
    :rtype: int
    """
    if not arr:
        return -1

    left = 0
    right = len(arr) - 1

    while left <= right:
        mid = (left + right) // 2

        if arr[mid] == target:
            if arr[mid - 1] == target:
                return mid
            else:
                right = mid - 1
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return -1

